"""Local explicit-property inspector, cumulative drafts and byte-preserving export."""
import base64
import json
from pathlib import Path
from adapters.native_selection import source_index

def write_viewer(manifest,profile):
    folder=Path(__file__).parent
    runtime='\n'.join((folder/name).read_text(encoding='utf-8') for name in ('title_runtime.js','appearance_runtime.js','native_selection_runtime.js'))
    index=source_index(base64.b64decode(manifest['source_base64']),manifest['source'])
    data=json.dumps({'manifest':manifest,'assets':profile['assets'],'native_source_index':index},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    page=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>观窗 · 外观编辑</title><style>
*{box-sizing:border-box}body{margin:0;background:#171b20;color:#e2e5e9;font:15px system-ui,"Microsoft YaHei",sans-serif}main{max-width:1440px;margin:auto;padding:24px}h1{font-size:25px;margin:0 0 8px}p{color:#b6c0cd;line-height:1.6}section{min-width:0;background:#222832;border:1px solid #3b4656;border-radius:8px;padding:18px;margin:16px 0}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr);gap:18px}label{display:block;margin:10px 0}input,select,button,textarea{font:inherit}input,select,textarea{width:100%;max-width:100%;background:#141a23;border:1px solid #526079;border-radius:4px;color:#eee;padding:8px}button{background:#386286;color:white;border:0;border-radius:5px;padding:9px 14px;margin:4px 6px 4px 0;cursor:pointer}button.secondary{background:#414c5b}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.status{min-height:26px;color:#90d6a2}.status.error{color:#ffa49d}.meta{font-size:13px;color:#adb9c9}.meta,.status{overflow-wrap:anywhere}#fullPreview{display:block;border:0;position:absolute;left:0;top:0;transform-origin:top left}#previewViewport{width:100%;overflow:auto}#previewSizer{position:relative}canvas{display:block;max-width:100%;background:#15191f;border:1px solid #465162}textarea{height:250px;font:12px ui-monospace,monospace}@media(max-width:800px){.grid{grid-template-columns:1fr}}
</style><main><h1>观窗 · 外观编辑</h1><p>选择控件并修改显式外观属性，累计修改会一起导出为完整 GUI。未编辑的字节与原逻辑保留；继承值和动态表达式不会被猜测替换。</p><p id="identity" class="meta"></p>
<section><details><summary>从原生编辑器观察定位控件</summary><p>导入观察记录和此工作区的原始 GUI，核对后选择对应控件。不会自动读取游戏，也不会改动当前草稿；未绑定控件和共享模板仅供查看。</p><label>观察记录 JSON<input id="nativeObservation" type="file" accept=".json"></label><label>当前原始 GUI<input id="nativeSource" type="file" accept=".gui"></label><button id="nativeLocate" type="button">定位观察控件</button><p id="nativeStatus" class="status" role="status"></p><pre id="nativeSnippet" hidden></pre></details></section>
<div class="grid"><section><label>控件<select id="target"></select></label><div id="fields"></div><p id="omitted" class="meta"></p><button id="resetTarget" class="secondary">恢复当前控件</button><button id="resetAll" class="secondary">恢复全部</button><button id="undo" class="secondary">撤销</button><button id="redo" class="secondary">重做</button></section>
<section><h2>控件局部示意</h2><p class="meta">用于查看尺寸、字号、颜色和已声明纹理；不是原生整窗渲染。位置以来源坐标显示。</p><canvas id="preview" width="640" height="240"></canvas><p id="localTextHint" class="meta"></p><p id="position" class="meta"></p><h2>累计修改</h2><pre id="diff"></pre><p id="status" class="status" role="status"></p><button id="export">导出完整 GUI</button><button id="request" class="secondary">导出编辑请求</button><button id="receipt" class="secondary">导出补丁记录</button><label>回读导出的 GUI<input id="reimport" type="file" accept=".gui"></label></section></div>
<section><details><summary>当前完整 GUI 草稿（只读）</summary><textarea id="source" readonly></textarea></details><p class="meta">下载完整 GUI 和编辑请求后，在观窗启动器选择「校验导出并生成最小差分」。命令行入口为 verify。</p></section></main>
<script id="data" type="application/json">__DATA__</script><script>__RUNTIME__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),M=D.manifest,A=GuanchuangAppearance,G=GuanchuangTitle,$=id=>document.getElementById(id);
const initial=()=>Object.fromEntries(Object.entries(M.targets).map(([k,t])=>[k,Object.fromEntries(Object.entries(t.fields).map(([f,v])=>[f,v.value]))]));
let values=initial(),selected=Object.keys(M.targets)[0],result=null,pending=Promise.resolve(),revision=0,undo=[],redo=[];const images={};let resolvedTexts={};
const labels={raw_text:'文字',fontsize:'字号',position_x:'横坐标',position_y:'纵坐标',width:'宽度',height:'高度',align:'对齐方式',texture:'纹理',color_r:'文字颜色 R',color_g:'文字颜色 G',color_b:'文字颜色 B',color_a:'文字透明度'};
const copy=v=>JSON.parse(JSON.stringify(v));
function status(t,error=false){$('status').textContent=t;$('status').className='status'+(error?' error':'')}
function edits(){const out={};for(const[alias,t]of Object.entries(M.targets)){const fields={};for(const[k,f]of Object.entries(t.fields))if(values[alias][k]!==f.value)fields[k]=values[alias][k];if(Object.keys(fields).length)out[alias]=fields}return out}
function draw(){window.refreshWholeLayout?.(values,selected);const c=$('preview').getContext('2d'),v=values[selected],t=M.targets[selected];c.clearRect(0,0,640,240);const w=v.width||240,h=v.height||80,scale=Math.min(1,600/w,200/h),dw=w*scale,dh=h*scale,x=(640-dw)/2,y=(240-dh)/2;c.fillStyle='#303b4a';c.fillRect(x,y,dw,dh);if(v.texture&&images[v.texture])c.drawImage(images[v.texture],x,y,dw,dh);c.strokeStyle='#8aa1bc';c.strokeRect(x,y,dw,dh);const channels=['r','g','b'].map(k=>Math.round((v['color_'+k]??0.9)*255));c.fillStyle='rgba('+channels.join(',')+','+(v.color_a??1)+')';c.font=Math.max(1,(v.fontsize||16)*scale)+'px system-ui';const align=String(v.align||'center').split('|')[0];c.textAlign=['left','right','center'].includes(align)?align:'center';c.textBaseline='middle';const tx=c.textAlign==='left'?x+4:c.textAlign==='right'?x+dw-4:320;c.save();c.beginPath();c.rect(x,y,dw,dh);c.clip();const shownText=v.raw_text??resolvedTexts[selected]??'';c.fillText(shownText,tx,120);c.restore();$('localTextHint').textContent=v.raw_text!=null?'文字来自当前显式编辑':resolvedTexts[selected]!=null?'文字来自整窗当前样本':t.source_text_read_only?'动态文字样本尚未加载':'此控件没有文字';$('position').textContent=`来源坐标 (${v.position_x??'继承'}, ${v.position_y??'继承'}) · ${w} × ${h} UI单位 · 本图比例 ${scale.toFixed(3)}`}
async function refresh(){const id=++revision;result=null;document.body.dataset.ready='0';try{const r=await A.apply(M,A.request(M,edits()));if(id!==revision)return;result=r;$('source').value=new TextDecoder().decode(r.bytes);$('diff').textContent=r.receipt.patches.length?r.receipt.patches.map(p=>p.field+': '+p.old_token+' → '+p.new_token).join('\n'):'尚未修改；导出与原GUI逐字节相同。';draw();document.body.dataset.ready='1';document.body.dataset.patchCount=String(r.receipt.patches.length);status('完整草稿已就绪，'+r.receipt.patches.length+'处最小补丁。')}catch(e){if(id===revision)status(e.message,true)}}
function update(){pending=refresh();return pending}
function controls(){const t=M.targets[selected];$('fields').replaceChildren();for(const[k,f]of Object.entries(t.fields)){const label=document.createElement('label');label.textContent=labels[k]||k;let input;if(k==='texture'){input=document.createElement('select');for(const value of M.texture_choices){const o=document.createElement('option');o.value=value;o.textContent=value;input.appendChild(o)}}else{input=document.createElement('input');input.type=['literal','align_word','align_string'].includes(f.encoder)?'text':'number';if(f.encoder==='component'){input.min='0';input.max='1';input.step='0.000001'}else if(input.type==='number')input.step='1'}input.value=String(values[selected][k]);input.dataset.field=k;const alias=selected;let editRecorded=false;input.onfocus=()=>{editRecorded=false};input.onblur=()=>{editRecorded=false};const commit=()=>{const value=input.type==='number'?Number(input.value):input.value;if(Object.is(values[alias][k],value))return;if(!editRecorded){undo.push(copy(values));redo=[];editRecorded=true}values[alias][k]=value;update()};input.oninput=commit;input.onchange=commit;label.appendChild(input);$('fields').appendChild(label)}$('omitted').textContent=Object.keys(t.omitted).length?'未开放的非唯一或动态属性：'+Object.keys(t.omitted).join('、'):''}
function restore(action){undo.push(copy(values));redo=[];action();controls();update()}
async function current(){let p;do{p=pending;await p}while(p!==pending);if(!result)throw new Error('请先修正输入');return result}
function download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
for(const[alias,t]of Object.entries(M.targets)){const o=document.createElement('option');o.value=alias;o.textContent=(t.name||alias)+' · '+t.type;$('target').appendChild(o)}
$('target').onchange=()=>{selected=$('target').value;controls();update()};$('resetTarget').onclick=()=>restore(()=>values[selected]=initial()[selected]);$('resetAll').onclick=()=>restore(()=>values=initial());
function selectNativeTarget(alias){selected=alias;$('target').value=alias;controls();draw()}
$('nativeLocate').onclick=async()=>{
const s=$('nativeStatus'),v=$('nativeSnippet'),f=$('nativeObservation').files[0],source=$('nativeSource').files[0];v.hidden=true;v.textContent='';
const unchanged=()=>{if(f!==$('nativeObservation').files[0]||source!==$('nativeSource').files[0])throw Error('选择的文件已变化，请重新定位')};
try{if(!f)throw Error('请选择观察记录');const h=JSON.parse(await f.text());
try{const alias=await GuanchuangNativeSelection.apply(M,h,source,D.native_source_index,id=>{unchanged();selectNativeTarget(id)});s.textContent='已定位：'+(M.targets[alias].name||alias)+'；草稿保留';s.className='status'}
catch(e){if(!['NODE_NOT_EDITABLE','SHARED_TEMPLATE_READ_ONLY'].includes(e.message))throw e;const n=await GuanchuangNativeSelection.inspect(D.native_source_index,h,source);unchanged();v.textContent=n.snippet;v.hidden=false;s.textContent=n.template_scope?'共享模板：只读，未切换编辑控件':'此源码节点未绑定可编辑属性：只读';s.className='status'}
}catch(e){s.textContent='未定位：'+e.message;s.className='status error'}};
$('undo').onclick=()=>{if(!undo.length)return;redo.push(copy(values));values=undo.pop();controls();update()};$('redo').onclick=()=>{if(!redo.length)return;undo.push(copy(values));values=redo.pop();controls();update()};
$('export').onclick=async()=>{try{const r=await current();download(M.source.split('/').pop(),r.bytes,'application/octet-stream')}catch(e){status(e.message,true)}};
for(const key of ['request','receipt'])$(key).onclick=async()=>{try{const r=await current();download('appearance-'+key+'.json',JSON.stringify(r[key],null,2),'application/json')}catch(e){status(e.message,true)}};
$('reimport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const r=await current();if(!G.equal(new Uint8Array(await f.arrayBuffer()),r.bytes))throw new Error('回读文件与当前草稿不同');status('回读的字节一致。在观窗启动器中选择「校验导出并生成最小差分」，即可完整重读源码。')}catch(e){status(e.message,true)}};
$('identity').textContent=M.source+' · '+M.window+' · SHA256 '+M.base_sha256;controls();
pending=Promise.all(Object.entries(D.assets).filter(([,a])=>a.preview_png_base64).map(([name,a])=>new Promise(resolve=>{const im=new Image();im.onload=()=>{images[name]=im;resolve()};im.onerror=resolve;im.src='data:image/png;base64,'+a.preview_png_base64}))).then(update);
window.__GUANCHUANG_APPEARANCE__={manifest:M,getValues:()=>copy(values),setEdit:(alias,field,value)=>{undo.push(copy(values));redo=[];values[alias][field]=value;controls();return update()},undo:()=>$('undo').click(),redo:()=>$('redo').click(),current};
</script></html>'''
    if profile.get('preview'):
        canvas=profile['preview'].get('canvas',{'w':1760,'h':990})
        panel='''<section><h2>绑定来源的整窗预览</h2><p class="meta">复用指定GUI模型与渲染器；预览草稿SHA256须与导出相同。当前支持显式绝对定位，原生像素效果另行验收。</p><label>样本状态<select id="previewState"></select></label><label>查看比例<select id="previewScale"><option value="fit">适应宽度</option><option value="1">100%</option></select></label><p id="previewScaleNote" class="meta"></p><p id="previewStatus" class="status"></p><div id="previewViewport"><div id="previewSizer"><iframe id="fullPreview" src="preview.html" title="来源绑定的整窗预览" width="__W__" height="__H__"></iframe></div></div></section>'''.replace('__W__',str(canvas['w'])).replace('__H__',str(canvas['h']))
        page=page.replace('<div class="grid"><section>',panel+'<div class="grid"><section>',1)
        preview_script=r'''
let previewLoaded=false,previewSequence=0;
const previewSize=__CANVAS__;
function fitPreview(){const scale=$('previewScale').value==='fit'?Math.min(1,$('previewViewport').clientWidth/previewSize.w):1;$('fullPreview').style.transform='scale('+scale+')';$('previewSizer').style.width=previewSize.w*scale+'px';$('previewSizer').style.height=previewSize.h*scale+'px';$('previewScaleNote').textContent='查看比例 '+Math.round(scale*100)+'% · 原画布 '+previewSize.w+'×'+previewSize.h+' UI单位';document.body.dataset.previewViewScale=String(scale)}
window.addEventListener('resize',fitPreview);$('previewScale').onchange=fitPreview;fitPreview();
for(const value of __STATES__){const o=document.createElement('option');o.value=value;o.textContent=value;$('previewState').appendChild(o)}
function sendPreview(){if(!previewLoaded||!result)return;$('fullPreview').contentWindow.postMessage({type:'guanchuang-appearance-values',values:copy(values),expected_sha256:result.receipt.after_sha256,state:$('previewState').value,version:++previewSequence},'*')}
window.addEventListener('message',event=>{if(event.source!==$('fullPreview').contentWindow)return;const data=event.data;if(data?.type==='guanchuang-appearance-ready'){previewLoaded=true;sendPreview()}else if(data?.type==='guanchuang-appearance-applied'&&data.version===previewSequence&&result&&data.sha256===result.receipt.after_sha256&&document.body.dataset.ready==='1'){resolvedTexts=data.resolved_texts||{};draw();$('previewStatus').textContent='整窗模型已同步 · 草稿SHA256 '+data.sha256;document.body.dataset.previewReady='1';document.body.dataset.previewSha256=data.sha256}else if(data?.type==='guanchuang-appearance-error'&&data.version===previewSequence){$('previewStatus').textContent='此修改暂无可靠整窗预览：'+data.message;document.body.dataset.previewReady='0'}});
$('previewState').onchange=()=>{document.body.dataset.previewReady='0';sendPreview()};
'''.replace('__STATES__',json.dumps(profile['preview']['states'],ensure_ascii=False).replace('<','\\u003c')).replace('__CANVAS__',json.dumps(canvas))
        page=page.replace("document.body.dataset.patchCount=String(r.receipt.patches.length);status(","document.body.dataset.patchCount=String(r.receipt.patches.length);document.body.dataset.previewReady='0';sendPreview();status(")
        page=page.replace("$('identity').textContent=M.source",preview_script+"\n$('identity').textContent=M.source",1)
